            await undo();
            expect(posted(post_message, 'setTransform')).toHaveLength(1);
            expect(cells_editable()).toEqual(HELD);
            await undo();
            await redo();
            expect(posted(post_message, 'setTransform')).toHaveLength(1);
            expect(warnings(post_message)).toEqual([]);

            // Cancelling is how a slow one is abandoned.
            await click_button('Cancel');
